package net.minecraft.world.phys;
public final class Vec3 {public final double x,y,z;public Vec3(double x,double y,double z){this.x=x;this.y=y;this.z=z;}public Vec3 add(Vec3 v){return new Vec3(x+v.x,y+v.y,z+v.z);}public Vec3 scale(double s){return new Vec3(x*s,y*s,z*s);}public boolean equals(Object other){return other instanceof Vec3 v&&Double.doubleToLongBits(x)==Double.doubleToLongBits(v.x)&&Double.doubleToLongBits(y)==Double.doubleToLongBits(v.y)&&Double.doubleToLongBits(z)==Double.doubleToLongBits(v.z);}public int hashCode(){return java.util.Objects.hash(x,y,z);}public String toString(){return "Vec3("+x+","+y+","+z+")";}}
